  ('may_dev_glosario_sch_core.idx_termino_maestros_maestro_id', 'index', coalesce(EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.oid = to_regclass('may_dev_glosario_sch_core.idx_termino_maestros_maestro_id') AND c.relkind IN ('i','I')), false)),
  ('may_dev_glosario_sch_core.idx_terminos_termino', 'index', coalesce(EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.oid = to_regclass('may_dev_glosario_sch_core.idx_terminos_termino') AND c.relkind IN ('i','I')), false))
)
